CREATE SCHEMA IF NOT EXISTS airtime;
SET LOCAL search_path=airtime,public;
CREATE TABLE settings(id boolean PRIMARY KEY DEFAULT true CHECK(id),config jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO settings(id) VALUES(true);
CREATE TABLE admin_users(id uuid PRIMARY KEY,email text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),last_login_at timestamptz);
CREATE TABLE campaigns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,title text NOT NULL,description text NOT NULL DEFAULT '',target_usd_cents bigint NOT NULL CHECK(target_usd_cents>0),committed_lamports bigint NOT NULL DEFAULT 0 CHECK(committed_lamports>=0),status text NOT NULL DEFAULT 'PLANNING' CHECK(status IN ('PLANNING','CREATIVE IN PROGRESS','SUBMITTED FOR REVIEW','APPROVED','FUNDED','SCHEDULED','LIVE','COMPLETED','REJECTED')),approval_status text NOT NULL DEFAULT 'NOT SUBMITTED' CHECK(approval_status IN ('NOT SUBMITTED','SUBMITTED FOR REVIEW','APPROVED','REJECTED')),approval_proof_url text,platform text NOT NULL DEFAULT '',format text NOT NULL DEFAULT '',video_url text,planned_start timestamptz,planned_end timestamptz,actual_start timestamptz,actual_end timestamptz,results text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(status NOT IN ('FUNDED','SCHEDULED','LIVE','COMPLETED') OR approval_status='APPROVED'),CHECK(approval_status<>'APPROVED' OR approval_proof_url IS NOT NULL));
CREATE TABLE sol_price_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),price_usd_micros bigint NOT NULL CHECK(price_usd_micros>0),source text NOT NULL,fetched_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX price_latest ON sol_price_snapshots(fetched_at DESC);
CREATE TABLE webhook_events(signature text PRIMARY KEY,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'DETECTED' CHECK(status IN ('DETECTED','VERIFYING','VERIFIED','UNCLASSIFIED','REJECTED','CONFIRMED','FAILED')),attempts int NOT NULL DEFAULT 0 CHECK(attempts>=0),error text,rpc_payload jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX pending_webhooks ON webhook_events(status,attempts,created_at);
CREATE TABLE creator_fee_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),signature text NOT NULL REFERENCES webhook_events(signature),event_index int NOT NULL,kind text NOT NULL CHECK(kind IN ('ACCRUAL','COLLECTION')),mint text,creator_wallet text NOT NULL,amount_lamports bigint NOT NULL CHECK(amount_lamports>=0),price_snapshot_id uuid REFERENCES sol_price_snapshots(id),usd_cents bigint,allocation_bps int NOT NULL CHECK(allocation_bps BETWEEN 0 AND 10000),allocation_lamports bigint NOT NULL CHECK(allocation_lamports>=0),venue text NOT NULL,evidence jsonb NOT NULL,verification_status text NOT NULL CHECK(verification_status IN ('VERIFIED','UNCLASSIFIED','REJECTED')),block_time timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(signature,event_index),CHECK(allocation_lamports=floor(amount_lamports::numeric*allocation_bps/10000)));
CREATE TABLE treasury_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),signature text NOT NULL UNIQUE REFERENCES webhook_events(signature),wallet text NOT NULL,kind text NOT NULL DEFAULT 'UNCLASSIFIED' CHECK(kind IN ('CREATOR_FEE_COLLECTION','FOUNDER_SEED','TREASURY_DEPOSIT','CAMPAIGN_EXPENDITURE','REFUND','ADMINISTRATIVE_ADJUSTMENT','INTERNAL_TRANSFER','UNCLASSIFIED')),amount_lamports bigint NOT NULL CHECK(amount_lamports>0),direction text NOT NULL CHECK(direction IN ('IN','OUT')),source_wallet text,price_snapshot_id uuid REFERENCES sol_price_snapshots(id),usd_cents bigint,advertising_bps int CHECK(advertising_bps BETWEEN 0 AND 10000),advertising_lamports bigint NOT NULL DEFAULT 0 CHECK(advertising_lamports>=0 AND advertising_lamports<=amount_lamports),fee_collection_id uuid UNIQUE REFERENCES creator_fee_events(id),status text NOT NULL CHECK(status IN ('DETECTED','VERIFYING','VERIFIED','UNCLASSIFIED','REJECTED','CONFIRMED','FAILED')),classification_source text NOT NULL DEFAULT 'UNCLASSIFIED',note text NOT NULL DEFAULT '',block_time timestamptz NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(advertising_lamports=0 OR (direction='IN' AND status='VERIFIED' AND kind IN ('CREATOR_FEE_COLLECTION','FOUNDER_SEED','REFUND'))),CHECK(kind<>'CREATOR_FEE_COLLECTION' OR fee_collection_id IS NOT NULL));
CREATE TABLE wallet_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),wallet text NOT NULL,balance_lamports bigint NOT NULL CHECK(balance_lamports>=0),slot bigint NOT NULL,commitment text NOT NULL CHECK(commitment='finalized'),synchronized_at timestamptz NOT NULL DEFAULT now(),UNIQUE(wallet,slot));
CREATE INDEX snapshots_latest ON wallet_snapshots(wallet,synchronized_at DESC);
CREATE TABLE campaign_expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES campaigns(id),amount_lamports bigint NOT NULL CHECK(amount_lamports>0),usd_cents bigint,price_snapshot_id uuid REFERENCES sol_price_snapshots(id),treasury_transaction_id uuid UNIQUE REFERENCES treasury_transactions(id),idempotency_key uuid NOT NULL UNIQUE,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE campaign_proof(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES campaigns(id),kind text NOT NULL CHECK(kind IN ('VIDEO','RECEIPT','PLACEMENT','RESULTS')),url text,object_path text,mime_type text,title text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK((url IS NOT NULL)::int+(object_path IS NOT NULL)::int=1));
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),admin_id uuid REFERENCES admin_users(id),action text NOT NULL,entity_id text,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sync_state(id boolean PRIMARY KEY DEFAULT true CHECK(id),last_success_at timestamptz,last_started_at timestamptz,last_webhook_at timestamptz,error text,alert text,cursors jsonb NOT NULL DEFAULT '{}',updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO sync_state(id) VALUES(true);
CREATE TABLE alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL,entity_id text NOT NULL,message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,entity_id));
CREATE TABLE rate_limits(key text PRIMARY KEY,count int NOT NULL,resets_at timestamptz NOT NULL);
CREATE FUNCTION touch_updated() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now();RETURN NEW;END $$;
CREATE TRIGGER campaigns_updated BEFORE UPDATE ON campaigns FOR EACH ROW EXECUTE FUNCTION touch_updated();
CREATE TRIGGER settings_updated BEFORE UPDATE ON settings FOR EACH ROW EXECUTE FUNCTION touch_updated();
CREATE TRIGGER ledger_updated BEFORE UPDATE ON treasury_transactions FOR EACH ROW EXECUTE FUNCTION touch_updated();
CREATE TRIGGER webhook_updated BEFORE UPDATE ON webhook_events FOR EACH ROW EXECUTE FUNCTION touch_updated();
CREATE FUNCTION guard_expense() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE c campaigns; total bigint; t treasury_transactions; BEGIN SELECT * INTO c FROM campaigns WHERE id=NEW.campaign_id FOR UPDATE;SELECT coalesce(sum(amount_lamports),0) INTO total FROM campaign_expenses WHERE campaign_id=c.id;IF c.status IN ('COMPLETED','REJECTED') OR total+NEW.amount_lamports>c.committed_lamports THEN RAISE EXCEPTION 'Expense exceeds campaign commitment';END IF;IF NEW.treasury_transaction_id IS NOT NULL THEN SELECT * INTO t FROM treasury_transactions WHERE id=NEW.treasury_transaction_id;IF t.status<>'VERIFIED' OR t.direction<>'OUT' OR t.amount_lamports<>NEW.amount_lamports THEN RAISE EXCEPTION 'Expense requires matching verified outflow';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER expense_eligibility BEFORE INSERT ON campaign_expenses FOR EACH ROW EXECUTE FUNCTION guard_expense();
CREATE FUNCTION guard_classification() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE e creator_fee_events; BEGIN IF NEW.kind='CREATOR_FEE_COLLECTION' THEN IF NEW.advertising_bps IS NULL OR NEW.advertising_lamports<>floor(NEW.amount_lamports::numeric*NEW.advertising_bps/10000) THEN RAISE EXCEPTION 'Exact advertising allocation required';END IF;SELECT * INTO e FROM creator_fee_events WHERE id=NEW.fee_collection_id;IF e.kind IS DISTINCT FROM 'COLLECTION' OR e.verification_status IS DISTINCT FROM 'VERIFIED' OR NEW.amount_lamports>e.amount_lamports THEN RAISE EXCEPTION 'Exact verified collection required';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER classification_proof BEFORE INSERT OR UPDATE ON treasury_transactions FOR EACH ROW EXECUTE FUNCTION guard_classification();
DO $$ DECLARE t text; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='airtime' LOOP EXECUTE format('ALTER TABLE airtime.%I ENABLE ROW LEVEL SECURITY',t);END LOOP;END $$;
REVOKE ALL ON SCHEMA airtime FROM PUBLIC;

ALTER TABLE treasury_transactions ADD COLUMN refund_expense_id uuid REFERENCES campaign_expenses(id);
CREATE TABLE fund_commitments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),campaign_id uuid NOT NULL REFERENCES campaigns(id),amount_lamports bigint NOT NULL CHECK(amount_lamports>0),idempotency_key uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE fund_commitments ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION freeze_funding_classification() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.advertising_lamports>0 AND (NEW.advertising_bps IS DISTINCT FROM OLD.advertising_bps OR NEW.advertising_lamports IS DISTINCT FROM OLD.advertising_lamports OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.fee_collection_id IS DISTINCT FROM OLD.fee_collection_id OR NEW.refund_expense_id IS DISTINCT FROM OLD.refund_expense_id OR NEW.status IS DISTINCT FROM OLD.status) THEN RAISE EXCEPTION 'Funded classification is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER funding_immutable BEFORE UPDATE ON treasury_transactions FOR EACH ROW EXECUTE FUNCTION freeze_funding_classification();

CREATE INDEX campaigns_status ON campaigns(status,created_at);
CREATE INDEX fee_history ON creator_fee_events(mint,kind,block_time DESC);
CREATE INDEX treasury_history ON treasury_transactions(block_time DESC);
CREATE INDEX expenses_campaign ON campaign_expenses(campaign_id);
CREATE INDEX proof_campaign ON campaign_proof(campaign_id);
CREATE INDEX audit_history ON audit_logs(created_at DESC);
CREATE INDEX rate_limit_expiry ON rate_limits(resets_at);
CREATE FUNCTION immutable_audit_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Accounting evidence is append-only';END $$;
CREATE TRIGGER expense_immutable BEFORE UPDATE OR DELETE ON campaign_expenses FOR EACH ROW EXECUTE FUNCTION immutable_audit_record();
CREATE TRIGGER commitment_immutable BEFORE UPDATE OR DELETE ON fund_commitments FOR EACH ROW EXECUTE FUNCTION immutable_audit_record();
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_audit_record();
CREATE FUNCTION protect_linked_expense() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM campaign_expenses WHERE treasury_transaction_id=OLD.id) AND (NEW.amount_lamports<>OLD.amount_lamports OR NEW.direction<>OLD.direction OR NEW.status<>OLD.status OR NEW.signature<>OLD.signature) THEN RAISE EXCEPTION 'Linked expenditure evidence is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER linked_expense_immutable BEFORE UPDATE ON treasury_transactions FOR EACH ROW EXECUTE FUNCTION protect_linked_expense();

CREATE FUNCTION guard_commitment_balance() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE delta bigint; allocated numeric; seeded numeric; spent numeric; reserved numeric; liquid numeric; BEGIN IF NEW.committed_lamports>OLD.committed_lamports THEN PERFORM pg_advisory_xact_lock(836244002);delta=NEW.committed_lamports-OLD.committed_lamports;IF NEW.approval_status<>'APPROVED' OR NEW.status IN ('COMPLETED','REJECTED') THEN RAISE EXCEPTION 'Commitment requires approved campaign';END IF;SELECT coalesce(sum(advertising_lamports),0) INTO allocated FROM treasury_transactions WHERE kind='CREATOR_FEE_COLLECTION' AND status='VERIFIED';SELECT coalesce(sum(advertising_lamports),0) INTO seeded FROM treasury_transactions WHERE kind='FOUNDER_SEED' AND status='VERIFIED';SELECT (SELECT coalesce(sum(amount_lamports),0) FROM campaign_expenses)-(SELECT coalesce(sum(advertising_lamports),0) FROM treasury_transactions WHERE kind='REFUND' AND status='VERIFIED') INTO spent;SELECT coalesce(sum(greatest(c.committed_lamports-coalesce((SELECT sum(amount_lamports) FROM campaign_expenses WHERE campaign_id=c.id),0),0)),0) INTO reserved FROM campaigns c WHERE c.status NOT IN ('COMPLETED','REJECTED');SELECT balance_lamports INTO liquid FROM wallet_snapshots WHERE wallet=(SELECT coalesce(config->>'treasury',(SELECT wallet FROM wallet_snapshots ORDER BY synchronized_at DESC LIMIT 1),'') FROM settings WHERE id=true) ORDER BY synchronized_at DESC LIMIT 1;IF liquid IS NULL OR delta>greatest(least(allocated+seeded-spent-reserved,liquid-reserved),0) THEN RAISE EXCEPTION 'Insufficient verified commitment balance';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER campaign_funding_balance BEFORE UPDATE OF committed_lamports ON campaigns FOR EACH ROW EXECUTE FUNCTION guard_commitment_balance();
